validator:
function validate(input) {
  const [{ Loans = [] }] = input;
  const ids = new Set();
  for (const [id, user, type] of Loans) {
    if (id === null || user === null || type === null) return 'Every loan needs a loan_id, a user_id and a loan_type.';
    if (ids.has(id)) return `loan_id ${id} appears twice.`;
    ids.add(id);
  }
  return null;
}

