function generate(rand, size) {
  const types = ['Mortgage', 'Refinance', 'AutoLoan', 'Inschool', 'Personal'];
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const users = size === 'small' ? 4 : 600;
  // Loan ids increase with random gaps, so they are unique; a shuffle then mixes their order.
  const Loans = [];
  let id = 0;
  for (let i = 0; i < count; i++) Loans.push([id += 1 + Math.floor(rand() * 50), 101 + Math.floor(rand() * users), types[Math.floor(rand() * types.length)]]);
  for (let i = Loans.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Loans[i], Loans[j]] = [Loans[j], Loans[i]]; }
  return [{ Loans }];
}
